import { useState, type FormEvent } from 'react';
import {
  Button,
  Card,
  Field,
  Form,
  Select,
  Stack,
  Switch,
  TextInput,
} from '@jinx-ui/react';

export type InterfaceLanguage = 'ru' | 'en';

export interface ProfileSettings {
  name: string;
  language: InterfaceLanguage;
  emailNotifications: boolean;
}

export interface ProfileSettingsFormProps {
  initialSettings?: Partial<ProfileSettings>;
  onSave: (settings: ProfileSettings) => void;
}

const LANGUAGE_OPTIONS: ReadonlyArray<{ value: InterfaceLanguage; label: string }> = [
  { value: 'ru', label: 'Русский' },
  { value: 'en', label: 'English' },
];

export default function ProfileSettingsForm({
  initialSettings,
  onSave,
}: ProfileSettingsFormProps) {
  const [name, setName] = useState(initialSettings?.name ?? '');
  const [language, setLanguage] = useState<InterfaceLanguage>(
    initialSettings?.language ?? 'ru',
  );
  const [emailNotifications, setEmailNotifications] = useState(
    initialSettings?.emailNotifications ?? false,
  );

  const trimmedName = name.trim();

  const handleSubmit = (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    if (!trimmedName) return;
    onSave({ name: trimmedName, language, emailNotifications });
  };

  return (
    <Card className="jx-card" style={{ padding: 'var(--jx-space-6)' }}>
      <Form onSubmit={handleSubmit} noValidate>
        <Stack direction="column" gap="var(--jx-space-5)">
          <Field label="Имя" htmlFor="profile-name">
            <TextInput
              id="profile-name"
              name="name"
              value={name}
              onChange={(event) => setName(event.target.value)}
              placeholder="Введите имя"
              autoComplete="name"
              required
            />
          </Field>

          <Field label="Язык интерфейса" htmlFor="profile-language">
            <Select
              id="profile-language"
              name="language"
              value={language}
              onChange={(event) =>
                setLanguage(event.target.value as InterfaceLanguage)
              }
            >
              {LANGUAGE_OPTIONS.map((option) => (
                <option key={option.value} value={option.value}>
                  {option.label}
                </option>
              ))}
            </Select>
          </Field>

          <Switch
            id="profile-email-notifications"
            name="emailNotifications"
            label="Уведомления на почту"
            checked={emailNotifications}
            onChange={(event) => setEmailNotifications(event.target.checked)}
          />

          <Button type="submit" variant="primary" disabled={!trimmedName}>
            Сохранить
          </Button>
        </Stack>
      </Form>
    </Card>
  );
}

